//go:build loong64

package floats

// Add32, Sub32, Mul32, Div32 and Sqrt32 LSX kernels (binop32.go), generated by
// go-asmgen (binop32_loong64_gen.go) into binop32_loong64.s, gated on hasLASX
// (lanes_loong64.go; every LASX CPU has LSX). One IEEE binary32 operation per
// element, no fused instruction: bit-identical to the portable loops. The callers
// pass every slice already sliced to the common length; an empty one never
// reaches a kernel.
//
//go:noescape
func add32LSX(dst, a, b *float32, n int)

//go:noescape
func sub32LSX(dst, a, b *float32, n int)

//go:noescape
func mul32LSX(dst, a, b *float32, n int)

//go:noescape
func div32LSX(dst, a, b *float32, n int)

//go:noescape
func sqrt32LSX(dst, src *float32, n int)

func add32(dst, a, b []float32) {
	if len(a) == 0 || !hasLASX {
		add32Ref(dst, a, b)
		return
	}
	add32LSX(&dst[0], &a[0], &b[0], len(a))
}

func sub32(dst, a, b []float32) {
	if len(a) == 0 || !hasLASX {
		sub32Ref(dst, a, b)
		return
	}
	sub32LSX(&dst[0], &a[0], &b[0], len(a))
}

func mul32(dst, a, b []float32) {
	if len(a) == 0 || !hasLASX {
		mul32Ref(dst, a, b)
		return
	}
	mul32LSX(&dst[0], &a[0], &b[0], len(a))
}

func div32(dst, a, b []float32) {
	if len(a) == 0 || !hasLASX {
		div32Ref(dst, a, b)
		return
	}
	div32LSX(&dst[0], &a[0], &b[0], len(a))
}

func sqrt32(dst, src []float32) {
	if len(src) == 0 || !hasLASX {
		sqrt32Ref(dst, src)
		return
	}
	sqrt32LSX(&dst[0], &src[0], len(src))
}
